30	type checkpointSummaryProvider struct {
31		Name        types.AgentName
32		DisplayName string
33		Model       string
34		Generator   summarize.Generator
35	}
36	
37	func resolveCheckpointSummaryProvider(ctx context.Context, w io.Writer) (*checkpointSummaryProvider, error) {
38		s, err := loadSummarySettings(ctx)
39		if err != nil {
40			return nil, fmt.Errorf("loading settings: %w", err)
41		}
42	
43		if s.SummaryGeneration != nil && s.SummaryGeneration.Provider != "" {
44			providerName := types.AgentName(s.SummaryGeneration.Provider)
45			if err := ensureSummaryProviderPresent(ctx, providerName); err != nil {
46				return nil, err
47			}
48			return buildCheckpointSummaryProvider(providerName, s.SummaryGeneration.Model)
49		}
50	
51		candidates := listEnabledSummaryProviders(ctx)
52	
53		switch len(candidates) {
54		case 0:
55			return nil, errors.New("no summary-capable agent CLI is installed on this machine; install one of claude, codex, gemini, cursor, or copilot, or set summary_generation.provider in settings")
56		case 1:
57			return autoSelectSummaryProvider(ctx, w, candidates[0].Name, "non-interactive auto-select: single installed provider")
58		default:
59			if !interactive.CanPromptInteractively() {
60				return autoSelectSummaryProvider(ctx, w, candidates[0].Name, "non-interactive auto-select: first detected of multiple")
61			}
62	
63			selected, err := promptForSummaryProvider(candidates)
64			if err != nil {
65				return nil, err
66			}
67			provider, err := autoSelectSummaryProvider(ctx, w, selected, "interactive prompt selection")
68			if err != nil {
69				return nil, err
70			}
71			fmt.Fprintf(w, "Using %s for summary generation.\n", provider.DisplayName)
72			return provider, nil
73		}
74	}
75	
76	// autoSelectSummaryProvider builds a provider for an auto-selected candidate
77	// (single-installed or non-interactive-first-of-many) and persists the choice
78	// so subsequent runs don't re-decide. Persistence failure is surfaced as a
79	// warning — not an error — because the selection is still usable in-process.
80	func autoSelectSummaryProvider(ctx context.Context, w io.Writer, name types.AgentName, reason string) (*checkpointSummaryProvider, error) {
81		logging.Info(ctx, reason, "provider", string(name))
82		provider, err := buildCheckpointSummaryProvider(name, "")
83		if err != nil {
84			return nil, err
85		}
86		if saveErr := persistSummaryProviderSelection(ctx, provider.Name, provider.Model); saveErr != nil {
87			logging.Warn(ctx, "failed to save summary provider selection, continuing without persistence",
88				"error", saveErr.Error())
89			fmt.Fprintf(w, "Warning: could not save provider selection: %v\nUse `entire configure --summarize-provider %s` to set it manually.\n", saveErr, provider.Name)
90		}
91		return provider, nil
92	}
93	
94	func listEnabledSummaryProviders(_ context.Context) []checkpointSummaryProvider {
95		registered := listRegisteredAgents()
96		providers := make([]checkpointSummaryProvider, 0, len(registered))
97		for _, name := range registered {
98			ag, err := getSummaryAgent(name)
99			if err != nil {
100				continue
101			}
102			if _, ok := agent.AsTextGenerator(ag); !ok {
103				continue
104			}
105			// Check CLI binary on PATH, not DetectPresence — a repo can use
106			// Claude Code for development while Codex is the summary provider.
107			if !isSummaryCLIAvailable(name) {
108				continue
109			}
110			providers = append(providers, checkpointSummaryProvider{
111				Name:        name,
112				DisplayName: string(ag.Type()),
113			})
114		}
115		return providers
116	}
117	
118	func promptForSummaryProvider(providers []checkpointSummaryProvider) (types.AgentName, error) {
119		options := make([]huh.Option[string], 0, len(providers))
120		for _, provider := range providers {
121			options = append(options, huh.NewOption(provider.DisplayName, string(provider.Name)))
122		}
123	
124		var selected string
125		form := NewAccessibleForm(
126			huh.NewGroup(
127				huh.NewSelect[string]().
128					Title("Choose a summary provider").
129					Description("This choice will be saved. Use `entire configure` to change it later.").
130					Options(options...).
131					Value(&selected),
132			),
133		)
134		if err := form.Run(); err != nil {
135			return "", fmt.Errorf("summary provider selection cancelled: %w", err)
136		}
137	
138		return types.AgentName(selected), nil
139	}
140	
141	func buildCheckpointSummaryProvider(name types.AgentName, model string) (*checkpointSummaryProvider, error) {
142		ag, err := getSummaryAgent(name)
143		if err != nil {
144			return nil, fmt.Errorf("loading summary provider %s: %w", name, err)
145		}
146	
147		textGenerator, ok := agent.AsTextGenerator(ag)
148		if !ok {
149			return nil, fmt.Errorf("agent %s does not support summary generation", name)
150		}
151	
152		effectiveModel := summarize.ResolveModel(name, model)
153	
154		return &checkpointSummaryProvider{
155			Name:        name,
156			DisplayName: string(ag.Type()),
157			Model:       effectiveModel,
158			Generator: &summarize.TextGeneratorAdapter{
159				TextGenerator: textGenerator,
160				Model:         effectiveModel,
161			},
162		}, nil
163	}
164	
165	// ensureSummaryProviderPresent returns an error if the named summary provider's
166	// CLI binary is not on PATH. Checks the binary directly (via exec.LookPath)
167	// rather than DetectPresence, because DetectPresence checks repo-level agent
168	// configuration — a repo using Claude Code for development can still use Codex
169	// or Gemini for summary generation as long as the binary is installed.
170	func ensureSummaryProviderPresent(_ context.Context, name types.AgentName) error {
171		if _, err := getSummaryAgent(name); err != nil {
172			return fmt.Errorf("unknown summary provider %s: %w", name, err)
173		}
174		if !isSummaryCLIAvailable(name) {
175			return fmt.Errorf("summary provider %q is configured but its CLI binary is not on PATH; install it or update summary_generation.provider in settings", name)
176		}
177		return nil
178	}
179	
180	func validateSummaryProvider(provider string) error {
181		name := types.AgentName(provider)
182		ag, err := getSummaryAgent(name)
183		if err != nil {
184			return fmt.Errorf("unknown summary provider %q: %w", provider, err)
185		}
186		if _, ok := agent.AsTextGenerator(ag); !ok {
187			return fmt.Errorf("agent %q does not support summary generation", provider)
188		}
189		if !isSummaryCLIAvailable(name) {
190			return fmt.Errorf("summary provider %q is configured but its CLI binary is not on PATH; install it or choose another provider", provider)
191		}
192		return nil
193	}
194	
195	func persistSummaryProviderSelection(ctx context.Context, provider types.AgentName, model string) error {
196		// Always write to settings.local.json: the provider choice is based on
197		// which CLI binaries are on the local PATH, so it is machine-specific
198		// and should not dirty the tracked settings.json.
199		targetFileAbs, err := paths.AbsPath(ctx, settings.EntireSettingsLocalFile)
200		if err != nil {
201			targetFileAbs = settings.EntireSettingsLocalFile
202		}
203	
204		s, err := loadSummarySettingsFromFile(targetFileAbs)
205		if err != nil {
206			return fmt.Errorf("loading settings for update: %w", err)
207		}
208		if s.SummaryGeneration == nil {
209			s.SummaryGeneration = &settings.SummaryGenerationSettings{}
210		}
211		s.SummaryGeneration.SetProvider(string(provider), model)
212	
213		if err := saveLocalSummarySettings(ctx, s); err != nil {
214			return fmt.Errorf("saving summary provider selection: %w", err)
215		}
216		return nil
217	}
218	
219	func formatSummaryProviderDetails(provider *checkpointSummaryProvider) string {
220		if provider == nil {
221			return ""
222		}
223		displayModel := provider.Model
224		if displayModel == "" {
225			displayModel = "provider default"
226		}
227		var b strings.Builder
228		fmt.Fprintf(&b, "Provider: %s\n", provider.DisplayName)
229		fmt.Fprintf(&b, "Model: %s\n", displayModel)
230		return b.String()
231	}
